insert into public.exercise_catalog (key, name, estado, ficha, tecnica, figura, revision, origen) values
('psoas', 'Estiramiento de psoas', 'publicado', $j${"nombre":"Estiramiento de psoas","zona":"Movilidad","para_que":"Estira la parte delantera de la cadera (psoas) para que la pelvis quede neutra; contrarresta estar sentado.","patron":"estiramiento_cadera","musculos":{"principales":["psoas"],"secundarios":["gluteo_mayor"]},"posicion":"rodilla_en_suelo","tipo":"isometrico","lados":"por_lado","material":[],"nivel":1,"regresion":null,"progresion":null,"sustitutos":[],"carga":{"lumbar":0,"rodilla":1,"hombro":0,"muneca":0,"cuello":0},"evitar_si":"Si duele la rodilla de apoyo, pon una toalla doblada debajo.","usos":["movilidad","calentar","recuperar"],"dosis":{"secs":30,"rango":[20,60],"tempo_s":null},"apuntes":[]}$j$::jsonb, $j${"revisado":true,"inicio":"De rodillas con una pierna adelantada: la rodilla de atrás y el empeine en el suelo, el pie de delante apoyado y esa rodilla a unos 90°. Tronco recto.","fases":[{"texto":"Postura: rodilla de atrás en el suelo, tronco recto","segundos":2.4,"tono":null,"apoyos":["rodilla","pies"]},{"texto":"Paso 1 · Aprieta fuerte el culo y mete el coxis hacia abajo","segundos":2.4,"tono":null,"apoyos":["rodilla","pies"]},{"texto":"Paso 2 · Sin soltar el culo, lleva la cadera adelante unos cm","segundos":4.4,"tono":null,"apoyos":["rodilla","pies"]}],"claves":["Las piernas no se mueven: rodilla de atrás y pie de delante quietos","Primero aprieta el culo de la pierna de atrás y mete el coxis","Después lleva la cadera unos centímetros adelante, con el tronco recto"],"errores":["Arquear la zona lumbar para avanzar: el estiramiento se va a la espalda","Llevar la rodilla de delante más allá del pie","Soltar el culo al llevar la cadera adelante"],"respiracion":"Respira lento y suelta el aire al llevar la cadera adelante.","lo_notas_en":"En la parte delantera de la cadera de la pierna de atrás; no en la zona lumbar ni en la rodilla.","condiciones":[{"angulo":{"articulacion":"rodilla","lado":"alguno","entre":[55,115]}},{"inclinacion":{"parte":"tronco","entre":[0,15]}},{"angulo":{"articulacion":"cadera","lado":"alguno","entre":[-45,10]},"fase":[1,2]},{"quieto":{"parte":"tobillo","cm":5}}],"no_medible":[],"video":"estiramiento psoas rodilla en el suelo fisioterapeuta"}$j$::jsonb, $j${"revisado":true,"apoya":"rodillas","hold":true,"marks":{"gl":{"at":["p"],"off":[-8,3],"lab":[38,20]},"ab":{"at":["c"],"off":[8,0]}},"stretch":{"segs":[["p","k1"]],"lab":[34,62]},"poses":[{"h":[95,14],"s":[95,27],"p":[95,62],"k1":[85,100.5],"a1":[44,98.3],"k2":[128,70],"a2":[128,100],"e1":[86,44],"w1":[93,60],"e2":[88,44],"w2":[95,60]},{"h":[96,14],"s":[96,27],"p":[97,63],"k1":[85,100.5],"a1":[44,98.3],"k2":[130,70],"a2":[128,100],"e1":[87,44],"w1":[95,60],"e2":[89,44],"w2":[97,60]},{"h":[103,15],"s":[103,28],"p":[104,64],"k1":[85,100.5],"a1":[44,98.3],"k2":[131,72],"a2":[128,100],"e1":[94,45],"w1":[102,61],"e2":[96,45],"w2":[104,61]}],"phases":[{"pose":0,"move":1,"hold":1.4,"cap":"Postura: rodilla de atrás en el suelo, tronco recto"},{"pose":1,"move":0.6,"hold":1.8,"cap":"Paso 1 · Aprieta fuerte el culo y mete el coxis hacia abajo","sq":["gl"],"arrow":[74,42,80,60]},{"pose":2,"move":1.8,"hold":2.6,"cap":"Paso 2 · Sin soltar el culo, lleva la cadera adelante unos cm","sq":["gl"],"arrow":[112,38,136,38],"stretch":true}]}$j$::jsonb, $j${"paso1":{"ok":true,"fecha":"2026-11-14","apuntes":[]},"paso2":{"ok":true,"fecha":"2026-11-13","comprobador":"node ejercicios/comprobar.js"},"paso3":{"ok":true,"fecha":"2026-11-13","comprobador":"node ejercicios/comprobar3d.js (hombre y mujer, cada fase y a mitad)","visto_bueno":"Claude, revisando capturas (claro y oscuro, grande y miniatura), por encargo del usuario"}}$j$::jsonb, 'rutina.json'),
('puente', 'Puente de glúteo', 'publicado', $j${"nombre":"Puente de glúteo","zona":"Glúteo","para_que":"Activa el glúteo y enseña a subir la cadera sin arquear la lumbar.","patron":"puente_cadera","musculos":{"principales":["gluteo_mayor"],"secundarios":["isquios","transverso"]},"posicion":"boca_arriba","tipo":"reps","lados":"bilateral","material":[],"nivel":1,"regresion":null,"progresion":"puente_banda","sustitutos":["puente_banda"],"carga":{"lumbar":1,"rodilla":0,"hombro":0,"muneca":0,"cuello":0},"evitar_si":"Si notas la lumbar más que el culo, sube menos.","usos":["core","fuerza","calentar"],"dosis":{"reps":15,"rango":[10,20],"tempo_s":4},"apuntes":[]}$j$::jsonb, $j${"revisado":true,"inicio":"Boca arriba, rodillas dobladas, pies apoyados a la anchura de la cadera y brazos en el suelo junto al cuerpo.","fases":[{"texto":"Sube en 1 s apretando el culo y aguanta 1 s arriba","segundos":2,"tono":"up","apoyos":["cabeza","espalda_alta","pies","brazos"]},{"texto":"Baja despacio (2 s) con el ombligo dentro","segundos":2,"tono":"down","apoyos":["cabeza","espalda_alta","espalda_baja","cadera","pies","brazos"]}],"claves":["Boca arriba, rodillas dobladas y pies apoyados","Antes de subir, aplana la zona lumbar contra el suelo","Sube la cadera apretando el culo, empujando con los talones","Arriba: hombros, cadera y rodillas en línea, sin arquear"],"errores":["Subir arqueando la zona lumbar: se nota en la espalda y no en el culo","Empujar con las puntas: se carga el cuádriceps","Abrir o cerrar las rodillas al subir"],"respiracion":"Suelta el aire al subir y cógelo al bajar.","lo_notas_en":"En el culo y algo en la parte de atrás del muslo; no en la zona lumbar.","condiciones":[{"angulo":{"articulacion":"rodilla","entre":[45,125]}},{"recto":{"puntos":["hombro","cadera","rodilla"],"tol":12},"fase":0},{"separados":{"partes":["pie_izq","pie_der"],"cm":5}}],"no_medible":[],"video":"puente de glúteo técnica correcta fisioterapeuta"}$j$::jsonb, $j${"revisado":true,"retro":22,"apoya":"tronco","rep":4,"unit":"Repetición","marks":{"gl":{"at":["p"],"off":[-2,5],"lab":[135,28]},"ab":{"at":["c"],"off":[0,-7],"lab":[40,62]}},"poses":[{"h":[26,98.8],"s":[40,101],"c":[65,102],"p":[90,98],"k1":[120,74],"a1":[135,100],"k2":[118,75],"a2":[133,100],"e1":[60,100],"w1":[78,100],"e2":[60,100],"w2":[78,100]},{"h":[28,86.5],"s":[46,95],"p":[95,72],"k1":[126,67],"a1":[135,100],"k2":[124,68],"a2":[133,100],"e1":[64,100],"w1":[82,100],"e2":[64,100],"w2":[82,100]}],"phases":[{"pose":1,"move":1,"hold":1,"tone":"up","cap":"Sube en 1 s apretando el culo y aguanta 1 s arriba","sq":["gl"],"arrow":[108,96,108,70]},{"pose":0,"move":1.5,"hold":0.5,"tone":"down","cap":"Baja despacio (2 s) con el ombligo dentro","sq":["ab"]}]}$j$::jsonb, $j${"paso1":{"ok":true,"fecha":"2026-11-14","apuntes":[]},"paso2":{"ok":true,"fecha":"2026-11-13","comprobador":"node ejercicios/comprobar.js"},"paso3":{"ok":true,"fecha":"2026-11-13","comprobador":"node ejercicios/comprobar3d.js (hombre y mujer, cada fase y a mitad)","visto_bueno":"Claude, revisando capturas (claro y oscuro, grande y miniatura), por encargo del usuario"}}$j$::jsonb, 'rutina.json'),
('deadbug', 'Dead bug', 'publicado', $j${"nombre":"Dead bug","zona":"Core","para_que":"Abdomen profundo: mover brazos y piernas sin que se despegue la lumbar.","patron":"anti_extension","musculos":{"principales":["recto_abdominal","transverso"],"secundarios":["oblicuos","psoas"]},"posicion":"boca_arriba","tipo":"reps","lados":"alterno","material":[],"nivel":1,"regresion":null,"progresion":"hollow_k","sustitutos":["hollow_k"],"carga":{"lumbar":0,"rodilla":0,"hombro":0,"muneca":0,"cuello":0},"evitar_si":"","usos":["core","calentar"],"dosis":{"reps":16,"rango":[8,20],"tempo_s":4},"apuntes":["Comprobar en 3D que la espalda apoya en el suelo (la comprobación 2D no sirve para los tumbados)"]}$j$::jsonb, $j${"revisado":true,"inicio":"Boca arriba con la zona lumbar pegada al suelo, brazos estirados hacia el techo y rodillas dobladas a 90° en el aire, encima de la cadera.","fases":[{"texto":"Estira un brazo atrás y la pierna contraria adelante (2 s)","segundos":2,"tono":"up","apoyos":["cabeza","espalda_alta","espalda_baja","cadera"]},{"texto":"Vuelve al centro (2 s), lumbar pegada al suelo","segundos":2,"tono":"down","apoyos":["cabeza","espalda_alta","espalda_baja","cadera"]},{"texto":"Ahora el otro brazo y la otra pierna (2 s)","segundos":2,"tono":"up","apoyos":["cabeza","espalda_alta","espalda_baja","cadera"]},{"texto":"Vuelve al centro (2 s)","segundos":2,"tono":"down","apoyos":["cabeza","espalda_alta","espalda_baja","cadera"]}],"claves":["Brazos al techo y rodillas dobladas a 90° encima de la cadera","Estira a la vez un brazo atrás y la pierna contraria adelante","La zona lumbar no se despega del suelo en ningún momento","Si se despega la espalda, estira menos"],"errores":["La zona lumbar se arquea al estirar: se nota en la espalda","Estirar el brazo y la pierna del mismo lado","Ir deprisa y dejar caer la pierna"],"respiracion":"Suelta el aire al estirar y cógelo al volver al centro.","lo_notas_en":"En la barriga, sobre todo abajo; no en la zona lumbar ni en el cuello.","condiciones":[{"angulo":{"articulacion":"rodilla","entre":[70,110]},"fase":[1,3]},{"angulo":{"articulacion":"cadera","entre":[70,110]},"fase":[1,3]},{"angulo":{"articulacion":"hombro","entre":[70,110]},"fase":[1,3]},{"angulo":{"articulacion":"rodilla","lado":"alguno","entre":[0,30]},"fase":[0,2]}],"no_medible":[],"video":"dead bug ejercicio técnica correcta"}$j$::jsonb, $j${"revisado":true,"retro":22,"apoya":"tronco","rep":4,"unit":"Repetición","marks":{"ab":{"at":["c"],"off":[0,-7],"lab":[80,18]}},"poses":[{"h":[30,96.8],"s":[44,99],"c":[70,100.5],"p":[95,96],"k1":[95,64],"a1":[125,64],"k2":[97,64],"a2":[127,64],"e1":[44,77],"w1":[44,59],"e2":[46,77],"w2":[46,59]},{"h":[30,96.8],"s":[44,99],"c":[70,100.5],"p":[95,96],"k1":[95,64],"a1":[125,64],"k2":[127,93],"a2":[158,90],"e1":[27,86],"w1":[10,92],"e2":[46,77],"w2":[46,59]},{"h":[30,96.8],"s":[44,99],"c":[70,100.5],"p":[95,96],"k1":[127,93],"a1":[158,90],"k2":[97,64],"a2":[127,64],"e1":[44,77],"w1":[44,59],"e2":[29,86],"w2":[12,92]}],"phases":[{"pose":1,"move":1.5,"hold":0.5,"tone":"up","cap":"Estira un brazo atrás y la pierna contraria adelante (2 s)","sq":["ab"],"arrow":[150,62,165,80]},{"pose":0,"move":1.5,"hold":0.5,"tone":"down","cap":"Vuelve al centro (2 s), lumbar pegada al suelo","sq":["ab"]},{"pose":2,"move":1.5,"hold":0.5,"tone":"up","cap":"Ahora el otro brazo y la otra pierna (2 s)","sq":["ab"],"arrow":[150,62,165,80]},{"pose":0,"move":1.5,"hold":0.5,"tone":"down","cap":"Vuelve al centro (2 s)","sq":["ab"]}]}$j$::jsonb, $j${"paso1":{"ok":true,"fecha":"2026-11-14","apuntes":["Comprobar en 3D que la espalda apoya en el suelo (la comprobación 2D no sirve para los tumbados)"]},"paso2":{"ok":true,"fecha":"2026-11-13","comprobador":"node ejercicios/comprobar.js"},"paso3":{"ok":true,"fecha":"2026-11-13","comprobador":"node ejercicios/comprobar3d.js (hombre y mujer, cada fase y a mitad)","visto_bueno":"Claude, revisando capturas (claro y oscuro, grande y miniatura), por encargo del usuario"}}$j$::jsonb, 'rutina.json'),
('plancha', 'Plancha con retroversión', 'publicado', $j${"nombre":"Plancha con retroversión","zona":"Core","para_que":"Aguantar el tronco recto contra la gravedad (anti-extensión) con la pelvis metida.","patron":"anti_extension","musculos":{"principales":["recto_abdominal","transverso"],"secundarios":["gluteo_mayor","deltoides_anterior","serrato"]},"posicion":"boca_abajo","tipo":"isometrico","lados":"bilateral","material":[],"nivel":1,"regresion":null,"progresion":null,"sustitutos":["deadbug","hollow_k"],"carga":{"lumbar":1,"rodilla":0,"hombro":1,"muneca":0,"cuello":0},"evitar_si":"Si notas la lumbar, cambia a dead bug.","usos":["core"],"dosis":{"secs":30,"rango":[15,60],"tempo_s":null},"apuntes":["La primera fase enseña el error («Así NO»): en el paso 2 decidir si se queda"]}$j$::jsonb, $j${"revisado":true,"inicio":"Boca abajo, apoyado en los antebrazos, con los codos debajo de los hombros, y en las puntas de los pies.","fases":[{"texto":"Apoya antebrazos y puntas: codos debajo de los hombros","segundos":2.4,"tono":null,"apoyos":["antebrazos","puntas_pies"]},{"texto":"Aprieta el culo y mete el ombligo: el cuerpo queda recto","segundos":3.6,"tono":null,"apoyos":["antebrazos","puntas_pies"]}],"claves":["Apoyado en antebrazos y puntas de los pies, codos debajo de los hombros","Aprieta el culo y mete el ombligo: la cadera se alinea","Mantén el cuerpo recto como una tabla","Mirada al suelo, cuello largo"],"errores":["La zona lumbar se hunde: se nota en la espalda (es el error más típico)","Subir mucho el culo: el ejercicio deja de trabajar la barriga","Aguantar el aire"],"respiracion":"Respira corto y normal, sin aguantar el aire.","lo_notas_en":"En la barriga y el culo; no en la zona lumbar.","condiciones":[{"angulo":{"articulacion":"hombro","entre":[65,110]}},{"angulo":{"articulacion":"codo","entre":[65,115]}},{"recto":{"puntos":["hombro","cadera","tobillo"],"tol":12},"fase":1}],"no_medible":[],"video":"plancha abdominal retroversión pélvica técnica"}$j$::jsonb, $j${"revisado":true,"hold":true,"marks":{"gl":{"at":["p"],"off":[2,-7],"lab":[135,40]},"ab":{"at":["c"],"off":[0,7],"lab":[36,40]}},"poses":[{"h":[28,68],"s":[42,73],"c":[71,77],"p":[100,78],"k1":[128,87.5],"a1":[156,95],"k2":[129,88.5],"a2":[157,95],"e1":[42,100],"w1":[22,100],"e2":[44,100],"w2":[24,100]},{"h":[28,68],"s":[42,73],"c":[71,75],"p":[100,76],"k1":[128,86],"a1":[156,95],"k2":[129,87],"a2":[157,95],"e1":[42,100],"w1":[22,100],"e2":[44,100],"w2":[24,100]}],"phases":[{"pose":0,"move":1,"hold":1.4,"cap":"Apoya antebrazos y puntas: codos debajo de los hombros"},{"pose":1,"move":1,"hold":2.6,"cap":"Aprieta el culo y mete el ombligo: el cuerpo queda recto","sq":["gl","ab"],"arrow":[88,100,88,84]}]}$j$::jsonb, $j${"paso1":{"ok":true,"fecha":"2026-11-14","apuntes":["La primera fase enseña el error («Así NO»): en el paso 2 decidir si se queda"]},"paso2":{"ok":true,"fecha":"2026-11-13","comprobador":"node ejercicios/comprobar.js"},"paso3":{"ok":true,"fecha":"2026-11-13","comprobador":"node ejercicios/comprobar3d.js (hombre y mujer, cada fase y a mitad)","visto_bueno":"Claude, revisando capturas (claro y oscuro, grande y miniatura), por encargo del usuario"}}$j$::jsonb, 'rutina.json'),
('gato', 'Gato-camello', 'publicado', $j${"nombre":"Gato-camello","zona":"Movilidad","para_que":"Mueve la columna entera, vértebra a vértebra, al ritmo de la respiración.","patron":"movilidad_columna","musculos":{"principales":["erectores","recto_abdominal"],"secundarios":[]},"posicion":"cuadrupedia","tipo":"reps","lados":"bilateral","material":[],"nivel":1,"regresion":null,"progresion":null,"sustitutos":[],"carga":{"lumbar":0,"rodilla":1,"hombro":0,"muneca":1,"cuello":0},"evitar_si":"Si duelen las muñecas, apóyate en los puños.","usos":["movilidad","calentar","recuperar"],"dosis":{"reps":6,"rango":[5,10],"tempo_s":7},"apuntes":[]}$j$::jsonb, $j${"revisado":true,"inicio":"A cuatro patas: manos debajo de los hombros y rodillas debajo de la cadera, con los empeines en el suelo.","fases":[{"texto":"Coge aire: deja caer la barriga y mira al frente","segundos":3.5,"tono":"down","apoyos":["manos","rodillas","espinillas"]},{"texto":"Suelta el aire: redondea la espalda y mete el ombligo","segundos":3.5,"tono":"up","apoyos":["manos","rodillas","espinillas"]}],"claves":["Manos debajo de los hombros, rodillas debajo de la cadera","Coge aire: deja caer la barriga y mira al frente","Suelta el aire: redondea la espalda hacia arriba y mira al ombligo","Movimiento lento, que empiece en la pelvis"],"errores":["Mover solo el cuello y no la espalda","Doblar los codos o echar el peso atrás","Ir rápido, sin respirar"],"respiracion":"Coge aire al dejar caer la barriga y suéltalo al redondear la espalda.","lo_notas_en":"A lo largo de toda la espalda, como un estiramiento suave; no debe doler.","condiciones":[{"angulo":{"articulacion":"hombro","entre":[40,110]}},{"angulo":{"articulacion":"cadera","entre":[65,110]}},{"angulo":{"articulacion":"codo","entre":[0,25]}}],"no_medible":[],"video":"gato camello ejercicio fisioterapia"}$j$::jsonb, $j${"revisado":true,"apoya":"rodillas","rep":7,"unit":"Respiración","marks":{"ab":{"at":["c"],"off":[0,8],"lab":[135,22]}},"poses":[{"h":[42,40],"s":[55,5