('crunch_inv', 'Crunch inverso', 'publicado', $j${"nombre":"Crunch inverso","zona":"Core","para_que":"Abdomen con flexión de tronco desde abajo: sube la pelvis, no las piernas.","patron":"flexion_tronco","musculos":{"principales":["recto_abdominal"],"secundarios":["transverso","oblicuos"]},"posicion":"boca_arriba","tipo":"reps","lados":"bilateral","material":[],"nivel":2,"regresion":null,"progresion":null,"sustitutos":["hollow_k","deadbug"],"carga":{"lumbar":1,"rodilla":0,"hombro":0,"muneca":0,"cuello":0},"evitar_si":"Si tiras con las piernas o con impulso, haz menos.","usos":["core","fuerza"],"dosis":{"reps":15,"rango":[8,20],"tempo_s":5},"apuntes":["La clave «Las 2–3 últimas tienen que costar» es de dosis, no de técnica"]}$j$::jsonb, $j${"revisado":true,"inicio":"Boca arriba, brazos en el suelo junto al cuerpo y rodillas dobladas a 90° en el aire, encima de la cadera.","fases":[{"texto":"Sube: rodillas al pecho, despega el coxis y aprieta 1 s","segundos":2,"tono":"up","apoyos":["cabeza","espalda_alta","espalda_baja","brazos"]},{"texto":"Baja muy despacio (3 s) sin arquear la lumbar","segundos":3,"tono":"down","apoyos":["cabeza","espalda_alta","espalda_baja","cadera","brazos"]}],"claves":["Rodillas dobladas a 90° en el aire, brazos en el suelo","Lleva las rodillas al pecho despegando solo el coxis","Sin impulso: sube con el abdomen, no con las piernas","Al bajar, la zona lumbar no se arquea"],"errores":["Balancear las piernas para subir","Despegar toda la espalda y cargar el cuello","Bajar de golpe arqueando la zona lumbar"],"respiracion":"Suelta el aire al subir y cógelo al bajar despacio.","lo_notas_en":"En la parte baja de la barriga; no en el cuello ni en la zona lumbar.","condiciones":[{"angulo":{"articulacion":"rodilla","entre":[60,120]}},{"angulo":{"articulacion":"cadera","entre":[105,150]},"fase":0},{"angulo":{"articulacion":"cadera","entre":[60,110]},"fase":1}],"no_medible":[],"video":"crunch inverso técnica correcta retroversión"}$j$::jsonb, $j${"revisado