('puente_banda', 'Puente de glúteo con banda', 'publicado', $j${"nombre":"Puente de glúteo con banda","zona":"Glúteo","para_que":"Puente con mini banda: glúteo mayor y también el medio (empujar las rodillas hacia fuera).","patron":"puente_cadera","musculos":{"principales":["gluteo_mayor","gluteo_medio"],"secundarios":["isquios","transverso"]},"posicion":"boca_arriba","tipo":"reps","lados":"bilateral","material":["banda"],"nivel":1,"regresion":"puente","progresion":"puente_abd","sustitutos":["puente"],"carga":{"lumbar":1,"rodilla":0,"hombro":0,"muneca":0,"cuello":0},"evitar_si":"Si notas la lumbar más que el culo, sube menos.","usos":["core","fuerza","calentar"],"dosis":{"reps":15,"rango":[10,20],"tempo_s":4},"apuntes":[]}$j$::jsonb, $j${"revisado":true,"inicio":"Boca arriba, rodillas dobladas, pies apoyados a la anchura de la cadera, mini banda por encima de las rodillas y brazos en el suelo.","fases":[{"texto":"Sube en 1 s apretando el culo y aguanta 1 s arriba","segundos":2,"tono":"up","apoyos":["cabeza","espalda_alta","pies","brazos"]},{"texto":"Baja despacio (2 s) con el ombligo dentro","segundos":2,"tono":"down","apoyos":["cabeza","espalda_alta","espalda_baja","cadera","pies","brazos"]}],"claves":["Banda por encima de las rodillas, pies a la anchura de la cadera","Antes de subir, aplana la zona lumbar contra el suelo","Sube apretando el culo y empujando las rodillas hacia fuera contra la banda","Arriba: hombros, cadera y rodillas en línea, sin arquear"],"errores":["Las rodillas se cierran hacia dentro","Subir arqueando la zona lumbar","Empujar con las puntas de los pies"],"respiracion":"Suelta el aire al subir y cógelo al bajar.","lo_notas_en":"En el culo, también en su parte de fuera; no en la zona lumbar.","condiciones":[{"angulo":{"articulacion":"rodilla","entre":[45,125]}},{"recto":{"puntos":["hombro","cadera","rodilla"],"tol":12},"fase":0},{"separados":{"partes":["pie_izq","pie_der"],"cm":5}}],"no_medible":[],"video":"puente de glúteo con banda en las rodi